var n=`1200-fry-jacks`;var a=`world-1200`;var t=`BZ`;var r=`central-america-caribbean`;var s=8;var o=49;var l={en:`Fry Jacks`,ua:`Фрай-джеки`};var d={en:`Fry Jacks is a dish from Belize prepared with all-purpose flour, baking powder. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Фрай-джеки, страва кухні країни Беліз, яку готують із таких продуктів: пшеничне борошно універсальне, розпушувач тіста. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var u=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 22 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 22 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:22,i:[[`all-purpose-flour`,480,`g`],[`baking-powder`,16,`g`],[`table-salt`,7,`g`],[`water`,240,`ml`],[`canola-oil`,35,`ml`]]},{en:`Shape, press or roll the prepared dough or mixture into portions appropriate to this dish.`,ua:`Розпластайте, розкачайте або сформуйте з підготовленого тіста чи маси порції потрібної форми.`,t:[`pressing`,`rolling-out-dough`],m:9,i:[]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 15 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 15 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:15,i:[[`canola-oil`,800,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`honey`,90,`g`]]}];var h={slug:n,id:a,country:`BZ`,region:r,servings:8,minutes:49,title:l,text:d,steps:u};export{t as country,h as default,a as id,o as minutes,r as region,s as servings,n as slug,u as steps,d as text,l as title};